gcms(){return"\u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u067e\u0644\u0646 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0628\u0628\u0646\u062f\u06cc\u062f\u061b \u0627\u06af\u0631 \u0631\u0648\u0634\u0646 \u0628\u0645\u0627\u0646\u062f\u060c \u0645\u062b\u0644 \u0633\u0627\u06cc\u0631 \u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u0633\u062a."},
gcmr(){return"\u0627\u0644\u0627\u0646 \u062f\u0631 \u0633\u0637\u062d \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a. \u0627\u0632 \u0645\u0633\u06cc\u0631 \xab\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u2192 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM\xbb (\u06cc\u0627 \u0645\u0646\u0648\u06cc \u0645\u0631\u0628\u0648\u0637) \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0686\u062a \u0648\u0628 \u0631\u0627 \u0631\u0648\u0634\u0646 \u06a9\u0646\u06cc\u062f\u060c \u0628\u0639\u062f \u0628\u0631\u06af\u0631\u062f\u06cc\u062f \u0648 \u0627\u06cc\u0646 \u0633\u0648\u06cc\u06cc\u0686 \u0631\u0627 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u0646\u06cc\u062f."},
gcmz(){return"\u0648\u06cc\u062c\u062a \u0641\u0639\u0627\u0644"},
gcmy(){return"\u0627\u06af\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0634\u0648\u062f\u060c \u0628\u0627 \u0647\u0645\u06cc\u0646 \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0645\u06a9\u0627\u0644\u0645\u0647\u0654 \u062c\u062f\u06cc\u062f \u0634\u0631\u0648\u0639 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f (\u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u06cc \u0642\u062f\u06cc\u0645 \u062f\u0631 \u067e\u0646\u0644 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f)."},
gcm0(){return"\u0644\u0637\u0641\u0627\u064b \xab\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a\xbb \u0631\u0627 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f (\u0645\u062b\u0644\u0627\u064b \u0646\u0627\u0645 \u0633\u0627\u06cc\u062a \u06cc\u0627 \u0628\u062e\u0634)."},
gclw(){return"\u0627\u06cc\u062c\u0627\u062f"},
gcmc(){return"\u0632\u0646\u062f\u0647 (WebSocket)"},
gcmf(){return"\u0646\u0638\u0631\u0633\u0646\u062c\u06cc"},
gcme(){return"\u0642\u0637\u0639"},
gcmd(){return"\u0628\u062f\u0648\u0646 \u06a9\u0644\u06cc\u062f"},
gcm5(){return"\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u062f\u0631 \u062d\u0627\u0644 \u062a\u0627\u06cc\u067e \u0627\u0633\u062a\u2026"},
gcmh(){return"\u0627\u0631\u0633\u0627\u0644 \u0634\u062f"},
gcmg(){return"\u062e\u0648\u0627\u0646\u062f\u0647 \u0634\u062f"},
gcli(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u0686\u062a \u0648\u0628"},
gclh(){return"\u067e\u06cc\u0627\u0645\u200c\u0647\u0627\u06cc \u0635\u0648\u062a\u06cc \u06a9\u0648\u062a\u0627\u0647 (\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u06cc\u0627 \u0627\u067e\u0631\u0627\u062a\u0648\u0631) \u0645\u0627\u0646\u0646\u062f \u0647\u0631 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062d\u0633\u0627\u0628 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."},
gcmw(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062a\u0648\u0633\u0637 \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0633\u0627\u06cc\u062a"},
gbg7(){return"\u0637\u0628\u0642 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0648 \u067e\u0644\u0646 \u0641\u0636\u0627. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0631\u0648\u06cc \u0647\u0645\u06cc\u0646 \u0648\u06cc\u062c\u062a \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gbg6(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062e\u0627\u0645\u0648\u0634 \u0627\u0633\u062a \u06cc\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0645\u062d\u062f\u0648\u062f \u0634\u062f\u0647 \u0627\u0633\u062a."},
gcmx(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a"},
gcls(){return"\u0631\u0647\u0627 \u06a9\u0646\u06cc\u062f \u062a\u0627 \u0627\u0631\u0633\u0627\u0644 \u0634\u0648\u062f"},
gcm_(){return"\u0636\u0628\u0637 \u0635\u062f\u0627 \u062f\u0631 \u0645\u0631\u0648\u0631\u06af\u0631 \u0627\u06cc\u0646 \u0646\u0633\u062e\u0647 \u062f\u0631 \u062f\u0633\u062a \u0646\u06cc\u0633\u062a\u061b \u0627\u0632 \u0627\u067e \u06cc\u0627 \u062f\u06a9\u0645\u0647\u0654 \u067e\u06cc\u0648\u0633\u062a \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f"},
gcmv(){return"\u0648\u06cc\u0633 \u0645\u0647\u0645\u0627\u0646 \u062e\u0627\u0645\u0648\u0634"},
gc2H(){return"\u0638\u0627\u0647\u0631 \u0628\u0631\u0646\u0627\u0645\u0647"},
gc2G(){return"\u0646\u062d\u0648\u0647\u0654 \u0646\u0645\u0627\u06cc\u0634 \u067e\u0646\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0631 \u062f\u0633\u06a9\u062a\u0627\u067e (\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f \u06cc\u0627 \u0686\u0646\u062f \u062a\u0628)"},
gbcu(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0638\u0627\u0647\u0631\u06cc"},
gca9(){return"\u067e\u0646\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 (\u062f\u0633\u06a9\u062a\u0627\u067e)"},
gcab(){return"\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f"},
gcac(){return"\u062f\u0631 \u0647\u0631 \u0632\u0645\u0627\u0646 \u0641\u0642\u0637 \u06cc\u06a9 \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0627\u0633\u062a (\u0646\u0627\u0648\u0628\u0631\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9)"},
gcad(){return"\u062a\u0628 \u062f\u0631 \u0646\u0648\u0627\u0631 \u0628\u0627\u0644\u0627"},
gcae(){return"\u0686\u0646\u062f \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0628\u0645\u0627\u0646\u062f \u0648 \u0628\u0627 \u062a\u0628\u200c\u0647\u0627\u06cc \u0646\u0648\u0627\u0631 \u062a\u06cc\u0631\u0647 \u0628\u0627\u0644\u0627\u06cc \u067e\u0646\u0644 \u062c\u0627\u0628\u0647\u200c\u062c\u0627 \u0634\u0648\u06cc\u062f (\u0641\u0642\u0637 \u062f\u0633\u06a9\u062a\u0627\u067e). \u062a\u0628\u200c\u0647\u0627\u06cc \u067e\u0633\u200c\u0632\u0645\u06cc\u0646\u0647 \u062f\u0631 \u062d\u0627\u0641\u0638\u0647 \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f\u061b \u06a9\u0644\u06cc\u062f \u067e\u0627\u06cc\u062f\u0627\u0631 \u0645\u0633\u06cc\u0631 \u0628\u0631\u0627\u06cc \u0628\u0627\u0632\u06af\u0634\u062a \u0628\u0647\u062a\u0631 \u0628\u0647 \u0647\u0645\u0627\u0646 \u062a\u0628 \u0647\u0645\u200c\u0633\u0648 \u0628\u0627 \u0631\u0648\u062a\u0631 \u0627\u0633\u062a."},
gcaa(){return"\u062d\u0627\u0644\u062a \u062a\u0628 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0631\u0636 \u0632\u06cc\u0627\u062f \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0648\u0628\u0627\u06cc\u0644 \u0647\u0645\u06cc\u0634\u0647 \u062d\u0627\u0644\u062a \u062a\u06a9\u200c\u0635\u0641\u062d\u0647 \u0627\u0633\u062a."},
gcah(){return"\u0630\u062e\u06cc\u0631\u0647 \u0634\u062f"},
gcag(){return"\u0630\u062e\u06cc\u0631\u0647\u0654 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062f"},
gcaf(){return"\u0630\u062e\u06cc\u0631\u0647"},
gcf4(){return"\u0628\u0633\u062a\u0646 \u0627\u06cc\u0646 \u062a\u0628"},
gcf3(){return"\u0628\u0633\u062a\u0646 \u062a\u0628\u200c\u0647\u0627\u06cc \u0631\u0627\u0633\u062a\u200c\u062a\u0631"},
gcf2(){return"\u0628\u0633\u062a\u0646 \u062a\u0628\u200c\u0647\u0627\u06cc \u0686\u067e\u200c\u062a\u0631"},
gcf0(){return"\u0647\u0645\u0647\u0654 \u062a\u0628\u200c\u0647\u0627"},
