gbdF(){return"\u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u067e\u06cc\u0646"},
gcf8(){return"\u062a\u0628 \u067e\u06cc\u0646\u200c\u0634\u062f\u0647"},
gcf7(){return"\u0627\u06cc\u0646 \u062a\u0628 \u067e\u06cc\u0646 \u0634\u062f\u0647 \u0627\u0633\u062a. \u0628\u0627 \u0628\u0633\u062a\u0646\u060c \u0627\u0632 \u0646\u0648\u0627\u0631 \u062a\u0628\u200c\u0647\u0627 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0622\u06cc\u0627 \u0645\u0637\u0645\u0626\u0646 \u0647\u0633\u062a\u06cc\u062f\u061f"},
gcf6(){return"\u0628\u0633\u062a\u0646 \u062a\u0628"},
gbdD(){return"\u062a\u0628 \u067e\u06cc\u0646 \u0634\u062f\u0647 \u2014 \u0628\u0631\u0627\u06cc \u0628\u0633\u062a\u0646 \u062a\u0623\u06cc\u06cc\u062f \u0644\u0627\u0632\u0645 \u0627\u0633\u062a"},
cf9(a){return""+a+" \u062a\u0628 \u067e\u06cc\u0646 \u062d\u0641\u0638 \u0634\u062f"},
