gcfc(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u062a\u0639\u0645\u06cc\u0631\u06af\u0627\u0647"},
gcam(){return"\u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u0627\u0632 \u0645\u0646\u0648\u06cc \u06a9\u0646\u0627\u0631\u06cc (\u0648\u0642\u062a\u06cc \u062a\u0628 \u0641\u0639\u0627\u0644 \u0627\u0633\u062a)"},
gcal(){return"\u0631\u0641\u062a\u0646 \u0628\u0647 \u062a\u0628 \u0645\u0648\u062c\u0648\u062f \u06cc\u0627 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0628 \u062c\u062f\u06cc\u062f"},
gcak(){return"\u0627\u06af\u0631 \u0647\u0645\u0627\u0646 \u0635\u0641\u062d\u0647 \u062f\u0631 \u06cc\u06a9\u06cc \u0627\u0632 \u062a\u0628\u200c\u0647\u0627 \u0628\u0627\u0632 \u0627\u0633\u062a \u0628\u0647 \u0647\u0645\u0627\u0646 \u0645\u06cc\u200c\u0631\u0648\u062f\u061b \u0648\u06af\u0631\u0646\u0647 \u062a\u0628 \u062c\u062f\u06cc\u062f \u0627\u0636\u0627\u0641\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f (\u0647\u0645\u0627\u0646 \u067e\u06cc\u0634\u200c\u0641\u0631\u0636 \u0642\u0628\u0644\u06cc)."},
