gcO9(){return"\u062e\u0631\u0648\u062c \u0627\u0632 \u0648\u06cc\u0631\u0627\u06cc\u0634"},
gcOs(){return"\u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u0647\u0627\u06cc \u0634\u0645\u0627"},
gcO3(){return"\u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627"},
gcOl(){return"\u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f"},
gcO5(){return"\u0627\u06cc\u062c\u0627\u062f \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631"},
gcOk(){return"\u0627\u0639\u0644\u0627\u0646\u06cc \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f"},
gbpx(){return"\u0645\u0634\u0627\u0647\u062f\u0647 \u0647\u0645\u0647"},
